"""Post-result teaching illustration; it does not select or alter the writer."""
from pathlib import Path
import json,importlib.util
D=Path(__file__).resolve().parents[1];A=D/'artifacts'
spec=importlib.util.spec_from_file_location('cycle',D/'src/run.py');x=importlib.util.module_from_spec(spec);spec.loader.exec_module(x);w=x.w
source,tables,targets,base,codec,cache=x.prepare();selected=json.loads((A/'RESULT.json').read_text())['selected'];assert selected;writer=w.c.Codec(x.MODEL,tables,selected['alphabets'],selected['assignment'])
lines=['rank\ttail\tsource_json\tcharacter_count']
for u,(rank,tail) in sorted(writer.encoded.items(),key=lambda z:(z[1][0],z[1][1])):lines.append(f'{rank}\t'+''.join(map(str,tail))+'\t'+json.dumps(u,ensure_ascii=False)+'\t'+str(len(u)))
(A/'MANUAL_INVERSE.tsv').write_text('\n'.join(lines)+'\n')
expected={};challenge=['# Table-only reading challenge','', 'These are artificial outputs of the selected writer, not manuscript text. No source-language inference is needed. Use only the supplied rules and inverse table. Each block starts a recipe with counter 0. Groups are delimited by spaces; the glyph-separated display below is only a reading aid. Decode every group and record state, style, rank, tail, fragment and source-word ending. Do not execute any codec or inspect source texts or EXPECTED files.','']
for label,book in [('A','b4'),('B','gr1')]:
 recipe=source[book][0];nums=writer.numeric(recipe['words']);stop=next(i+1 for i,row in enumerate(nums) if i+1>=8 and 25<=row[-1]<=27);groups=writer.render(nums[:stop]);decoded=writer.decode([w.m.glyphs(g) for g in groups]);expected[label]={'book':book,'recipe_id':recipe['id'],'groups':groups,'words':decoded};challenge.extend(['## '+label,'',' '.join(groups),'','| Group | Glyphs |','|---:|---|']+[f'| {i+1} | '+ ' · '.join(w.m.glyphs(g))+' |' for i,g in enumerate(groups)]+[''])
(A/'MANUAL_CHALLENGE.md').write_text('\n'.join(challenge)+'\n');(A/'MANUAL_EXPECTED.json').write_text(json.dumps(expected,indent=2,ensure_ascii=False)+'\n')
a=selected['alphabets'];rules=['# Manual rules for the artificial writer','', 'Working glyphs: '+ ' '.join(w.m.SIGNS) if hasattr(w.m,'SIGNS') else '# Manual rules', '', 'Start each recipe with state 0 and no previous character. For each group select style: recipe-first if no previous character; after-punctuation if the previous decoded character is one of . , ; : ! ?; otherwise ordinary. Line wraps do not reset anything.','', '| Position (zero based) | Ordinary | Recipe-first | After-punctuation |','|---:|---|---|---|']
for j in range(7):rules.append(f'| {j} | {a["initial"][j]} | {a["initial"][7+j]} | {a["initial"][14+j]} |')
rules+=['', 'Find the first glyph in the applicable row/column bank. If its position is p, the dictionary rank is (p − state) modulo 7 (use a result from 0 to 6). The remaining 22nd entry of the full initial map has no role as an initial.', '', '| Digit | Interior glyph | Final glyph: word ends | Final glyph: word continues |','|---:|---|---|---|']
for j in range(3):rules.append(f'| {j} | {a["medial"][j]} | {a["final"][j]} | {a["final"][j+3]} |')
rules+=['', 'Read all glyphs after the initial as digits, using the interior column except for the last glyph. The final glyph identifies both its digit and whether the source word ends. The full digit string is the tail. Look up (rank, tail) in MANUAL_INVERSE.tsv. The source_json field is a literal source fragment, not a Voynich meaning. Append the fragment to the pending source word. At an end-final emit that word and clear the pending word.','', 'Then add the character_count of that fragment to the counter and take modulo 6. Set previous character to the fragment’s last decoded character. Repeat. Source spaces do not increment the counter.','', 'For writing, scan each source word from left to right and choose the longest dictionary fragment matching the remaining letters (down to one character). Look up its rank and tail. Use initial position (rank + state) modulo 7 in the applicable style bank. Interior digits use the interior column; the last digit uses end or continue according to whether this fragment completes the source word. Update state as above. A blank recipe boundary resets it.','', 'The full dictionary has 2,130 entries. The procedural steps are small; preparing, copying and searching that table is a substantial cost. A short correct manual read does not establish medieval practicality.']
(A/'MANUAL_RULES.md').write_text('\n'.join(rules)+'\n');print(json.dumps({'challenge_group_counts':{k:len(v['groups']) for k,v in expected.items()},'table_entries':len(writer.encoded)}))
